package org.apache.commons.cli;

import java.io.*;
import java.io.PrintWriter;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

public class HelpFormatter_findWrapPos_TriageGen0Test {

    private HelpFormatter helpFormatter;

    @Before
    public void setup() {
        helpFormatter = new HelpFormatter();
    }

    @Test
    public void testFindWrapPosLineBreakBeforeWrapWidth() {
        //Arrange
        String text = "Hello World\n";
        int width = 10;
        int startPos = 0;

        //Act
        int result = helpFormatter.findWrapPos(text, width, startPos);

        //Assert
        assertEquals(6, result);
    }

    @Test
    public void testFindWrapPosTabBeforeWrapWidth() {
        //Arrange
        String text = "Hello\tWorld";
        int width = 10;
        int startPos = 0;

        //Act
        int result = helpFormatter.findWrapPos(text, width, startPos);

        //Assert
        assertEquals(6, result);
    }

    @Test
    public void testFindWrapPosLineBreakAtWrapWidth() {
        //Arrange
        String text = "Hello World\n";
        int width = 5;
        int startPos = 0;

        //Act
        int result = helpFormatter.findWrapPos(text, width, startPos);

        //Assert
        assertEquals(0, result);
    }

    @Test
    public void testFindWrapPosTabAtWrapWidth() {
        //Arrange
        String text = "Hello\tWorld";
        int width = 5;
        int startPos = 0;

        //Act
        int result = helpFormatter.findWrapPos(text, width, startPos);

        //Assert
        assertEquals(0, result);
    }

    @Test
    public void testFindWrapPosNoLineBreakNoTabBeforeWrapWidth() {
        //Arrange
        String text = "HelloWorld";
        int width = 10;
        int startPos = 0;

        //Act
        int result = helpFormatter.findWrapPos(text, width, startPos);

        //Assert
        assertEquals(10, result);
    }

    @Test
    public void testFindWrapPosNoLineBreakNoTabAtWrapWidth() {
        //Arrange
        String text = "HelloWorld";
        int width = 5;
        int startPos = 0;

        //Act
        int result = helpFormatter.findWrapPos(text, width, startPos);

        //Assert
        assertEquals(5, result);
    }

    @Test
    public void testFindWrapPosNoLineBreakNoTabBeforeWrapWidthAndReturnMinusOne() {
        //Arrange
        String text = "HelloWorld";
        int width = 10;
        int startPos = 5;

        //Act
        int result = helpFormatter.findWrapPos(text, width, startPos);

        //Assert
        assertEquals(-1, result);
    }

    @Test
    public void testFindWrapPosNoLineBreakNoTabAtWrapWidthAndReturnMinusOne() {
        //Arrange
        String text = "HelloWorld";
        int width = 5;
        int startPos = 5;

        //Act
        int result = helpFormatter.findWrapPos(text, width, startPos);

        //Assert
        assertEquals(-1, result);
    }

    @Test
    public void testFindWrapPosEmptyText() {
        //Arrange
        String text = "";
        int width = 10;
        int startPos = 0;

        //Act and Assert
        assertThrows(IllegalArgumentException.class, () -> helpFormatter.findWrapPos(text, width, startPos));
    }

    @Test
    public void testFindWrapPosNullText() {
        //Arrange
        String text = null;
        int width = 10;
        int startPos = 0;

        //Act and Assert
        assertThrows(NullPointerException.class, () -> helpFormatter.findWrapPos(text, width, startPos));
    }

    @Test
    public void testFindWrapPosNegativeWidth() {
        //Arrange
        String text = "Hello World";
        int width = -10;
        int startPos = 0;

        //Act and Assert
        assertThrows(IllegalArgumentException.class, () -> helpFormatter.findWrapPos(text, width, startPos));
    }

    @Test
    public void testFindWrapPosNegativeStartPos() {
        //Arrange
        String text = "Hello World";
        int width = 10;
        int startPos = -10;

        //Act and Assert
        assertThrows(IllegalArgumentException.class, () -> helpFormatter.findWrapPos(text, width, startPos));
    }

    @Test
    public void testFindWrapPosStartPosEqualToTextLength() {
        //Arrange
        String text = "Hello World";
        int width = 10;
        int startPos = text.length();

        //Act and Assert
        assertThrows(IllegalArgumentException.class, () -> helpFormatter.findWrapPos(text, width, startPos));
    }
}
